// Static reference content of the Phase 3 specification (Machiavellian Strategic Influence), kept as data so the tabs, the prompts and the tests read one source.
// A text is either a plain English string (English only, and the interface says so) or { en, ar } where both languages are provided.
export type T = string | { en: string; ar: string };
export const tx = (v: T, L: "en" | "ar") => (typeof v === "string" ? v : v[L]);
export const hasAr = (v: T) => typeof v !== "string";

/** Section 1: five outcomes that are often treated as equivalent. */
export const OUTCOMES: { id: string; name: T; meaning: T; evidence: string }[] = [
  { id: "access", name: { en: "Access", ar: "الوصول" }, meaning: { en: "Ability to hold substantive official dialogue or take part in legitimate forums", ar: "القدرة على إجراء حوار رسمي جوهري أو المشاركة في منتديات مشروعة" }, evidence: "Institutional channels and documented engagement" },
  { id: "commercial", name: { en: "Commercial presence", ar: "الحضور التجاري" }, meaning: { en: "Trade, investment and operating activity", ar: "التجارة والاستثمار والنشاط التشغيلي" }, evidence: "Actual transactions, operating assets, returns and exposure" },
  { id: "agenda", name: { en: "Agenda contribution", ar: "المساهمة في جدول الأعمال" }, meaning: { en: "Ability to advance proposals that receive substantive consideration", ar: "القدرة على طرح مقترحات تحظى بنظر جوهري" }, evidence: "Negotiation records, adopted proposals and follow-through" },
  { id: "durable", name: { en: "Durable cooperation", ar: "التعاون الدائم" }, meaning: { en: "Arrangements that survive leadership, economic and geopolitical change", ar: "ترتيبات تصمد أمام تغيّر القيادات والاقتصاد والجغرافيا السياسية" }, evidence: "Implemented agreements and continuity over time" },
  { id: "autonomy", name: { en: "Strategic autonomy", ar: "الاستقلال الاستراتيجي" }, meaning: { en: "UAE ability to retain options and withstand disruption", ar: "قدرة الإمارات على الاحتفاظ بخياراتها وتحمّل الاضطراب" }, evidence: "Diversified relationships, capability and stress-test evidence" },
];

/** Section 2: Machiavelli as a critical lens. Chapter numbers follow the Marriott translation on Project Gutenberg (R1); the adaptations are design choices of this module, not quotations or claims about what Machiavelli endorsed. */
export const LENS = {
  questions: [
    { en: "What does the counterpart actually need?", ar: "ما الذي يحتاجه الطرف المقابل فعلًا؟" }, { en: "What can the UAE deliver better than alternatives?", ar: "ما الذي تستطيع الإمارات تقديمه أفضل من البدائل؟" }, { en: "Which promises are affordable?", ar: "أي الوعود يمكن تحمّل كلفتها؟" }, { en: "What would change under new leadership?", ar: "ما الذي سيتغير في ظل قيادة جديدة؟" },
    { en: "Which commitments create future liabilities?", ar: "أي الالتزامات تخلق أعباء مستقبلية؟" }, { en: "Where does apparent strength conceal dependence?", ar: "أين تُخفي القوة الظاهرة اعتمادًا على الغير؟" }, { en: "What evidence would show that the strategy is failing?", ar: "ما الدليل الذي يُظهر أن الاستراتيجية تفشل؟" },
  ] as { en: string; ar: string }[],
  adaptations: [
    { ch: "Ch. XVII and XIX (reputation, being despised or hated)", adapt: { en: "Treat conduct as reputational capital: test how each move will be read by the counterpart, its public and third parties, and avoid commitments that invite resentment.", ar: "عامِل السلوك كرأسمال سمعة: اختبر كيف سيُقرأ كل إجراء لدى الطرف المقابل وجمهوره والأطراف الثالثة، وتجنّب التزامات تستجلب الاستياء." }, limit: "A Renaissance prince's problem of personal rule does not transfer to institutions with public scrutiny and law." },
    { ch: "Ch. XXII (the prince's ministers)", adapt: { en: "Obtain unwelcome advice: require an independent challenger and keep dissent in the record.", ar: "احصل على المشورة غير المرحّب بها: اشترط خصمًا مستقلًا وأبقِ الخلاف في السجل." }, limit: "Advice quality depends on the adviser's independence, which a process can support but not guarantee." },
    { ch: "Ch. XXIII (avoiding flatterers)", adapt: { en: "Distrust good news that comes only from the party that gains from it; verify against independent sources.", ar: "تشكّك في الأخبار الجيدة التي تأتي من الطرف المستفيد وحده؛ وتحقق من مصادر مستقلة." }, limit: "Independence of sources has to be shown, not assumed." },
    { ch: "Ch. XX (fortresses and similar expedients)", adapt: { en: "Assess dependence on others: map which of the UAE's positions rest on a single supplier, route, partner or office-holder.", ar: "قيّم الاعتماد على الغير: حدّد مواقع الإمارات التي تستند إلى مورّد أو مسار أو شريك أو شخص واحد." }, limit: "The chapter concerns defending a prince's hold on territory, not partnership design." },
    { ch: "Ch. XXV (fortune)", adapt: { en: "Revise strategy when circumstances change: set review triggers and reversible steps instead of fixed ten-year plans.", ar: "راجِع الاستراتيجية عند تغيّر الظروف: ضع محفّزات مراجعة وخطوات قابلة للعكس بدل خطط عشرية جامدة." }, limit: "A metaphor about adaptation, not a forecasting method." },
    { ch: "Ch. XXIV, XXVI (modern analogies)", adapt: { en: "Examine interests behind rhetoric and test capability against ambition.", ar: "افحص المصالح الكامنة وراء الخطاب واختبر القدرة مقابل الطموح." }, limit: "Used as a prompt for questions, never as authority for a recommendation." },
  ],
  note: { en: "Machiavelli is used as a historical lens, not an instruction manual. These are design adaptations, not quotations, and the module never dresses an unsupported recommendation in a historical quotation.", ar: "يُستخدم ميكيافيلي عدسة تاريخية لا دليل تعليمات. هذه تكييفات تصميمية لا اقتباسات، ولا تُلبس الوحدة توصية غير مدعومة ثوب اقتباس تاريخي." },
};

/** Section 5: power instruments and their limits. */
export type Instrument = { id: string; name: T; contribution: T; checks: string; kind: "soft" | "hard" | "mixed" };
